/**
 * Worker-owned, versioned official LastRO option metadata.
 *
 * This bundle is deliberately independent from D1. Both the Worker validator and
 * the Web options endpoint use this same source of truth, so option metadata does
 * not consume database reads and cannot drift between clients.
 */

export const OPTION_DEFINITIONS_VERSION = 'options-lastro-71.0' as const;

export interface StaticOptionDefinition {
  type: number;
  handle: string;
  labelZh: string;
  descriptionTemplate: string;
  valueType: 'integer' | 'scaled_integer';
  /**
   * 'flag' options carry no magnitude: stored option_value is always 0 and the
   * only meaningful predicate is equality. Omitted means a regular numeric value.
   */
  valuePolicy?: 'numeric' | 'flag';
  /** Sentinel slots (e.g. type 204) are stored types but never user-selectable. */
  selectable?: boolean;
  unit: string;
  scale: number;
  allowedOperators: Array<'eq' | 'neq' | 'gt' | 'gte' | 'lt' | 'lte'>;
  paramPolicy:
    | { mode: 'ignored'; filterable: false }
    | { mode: 'required_exact'; filterable: true; value?: number }
    | { mode: 'optional_exact'; filterable: true; value?: number };
  repeatPolicy: 'same' | 'distinct';
  displayTemplate: string;
  searchTokens: string[];
}

