export const OPTION_DEFINITION_MAP = new Map<number, StaticOptionDefinition>(
  OPTION_DEFINITIONS.map((definition) => [definition.type, definition]),
);

export function getOptionDefinitionSet(version?: string): { version: string; items: StaticOptionDefinition[] } {
  if (version !== undefined && version !== 'unpublished' && version !== OPTION_DEFINITIONS_VERSION) {
    throw Object.assign(new Error('Unknown option version'), { status: 400 });
  }
  return { version: OPTION_DEFINITIONS_VERSION, items: OPTION_DEFINITIONS };
}
